import type { Persona } from '@wener/ai/agent/persona';
import type { ComponentPropsWithRef } from 'react';
import type {
	AiConfigEditorSlots,
	AiConfigSchema,
	AiConfigValidationMode,
	AiResourceEditorMessageOverrides,
	AiResourceEditorMessages,
} from '../../ui/ai-config-editor';

export type AgentPersonaEditorField =
	| 'id'
	| 'name'
	| 'version'
	| 'title'
	| 'nickname'
	| 'description'
	| 'author'
	| 'creatorNotes'
	| 'tags'
	| 'language'
	| 'authoring'
	| 'prompts'
	| 'greetings'
	| 'groupGreetings'
	| 'lorebook'
	| 'assets'
	| 'governance'
	| 'rights'
	| 'metadata'
	| 'extensions';
export type AgentPersonaEditorSection =
	| 'identity'
	| 'authoring'
	| 'prompts'
	| 'author'
	| 'lorebook'
	| 'assets'
	| 'governance'
	| 'extensions';
export type AgentPersonaEditorMessages = AiResourceEditorMessages<AgentPersonaEditorField, AgentPersonaEditorSection>;
export type AgentPersonaEditorMessageOverrides = AiResourceEditorMessageOverrides<
	AgentPersonaEditorField,
	AgentPersonaEditorSection
>;
export type AgentPersonaEditorProps = Omit<ComponentPropsWithRef<'div'>, 'onChange' | 'title'> & {
	value: Persona;
	onChange: (value: Persona) => void;
	onSubmit?: (value: Persona) => void;
	schema?: AiConfigSchema<Persona>;
	validationMode?: AiConfigValidationMode;
	disabled?: boolean;
	readOnly?: boolean;
	messages?: AgentPersonaEditorMessageOverrides;
	slots?: AiConfigEditorSlots<Persona>;
	maxLoreEntries?: number;
	maxAssets?: number;
};

'use client';

import type { LorebookEntry, PersonaLorebook } from '@wener/ai/agent/persona';
import { Plus, Trash2 } from 'lucide-react';
import type { ComponentPropsWithRef } from 'react';
import {
	AiConfigFieldGrid,
	AiConfigNumberField,
	AiConfigStringListField,
	AiConfigTextareaField,
	AiConfigTextField,
	AiConfigToggleField,
	JsonValueEditor,
	useStableListEntries,
} from '../../ui/ai-config-editor';

export type PersonaLorebookEditorProps = Omit<ComponentPropsWithRef<'div'>, 'onChange'> & {
	value?: PersonaLorebook;
	onChange: (value: PersonaLorebook) => void;
	disabled?: boolean;
	readOnly?: boolean;
	maxEntries?: number;
};

export function PersonaLorebookEditor({
	value,
	onChange,
	disabled = false,
	readOnly = false,
	maxEntries = 64,
	className,
	...props
}: PersonaLorebookEditorProps) {
	const lorebook: PersonaLorebook = value ?? { entries: [], bindings: [] };
	const boundedMax = Number.isInteger(maxEntries) ? Math.max(1, Math.min(maxEntries, 256)) : 64;
	const loreEntries = useStableListEntries(lorebook.entries, 'lore-entry');
	const updateEntry = (index: number, entry: LorebookEntry) =>
		onChange({
			...lorebook,
			entries: lorebook.entries.map((current, itemIndex) => (itemIndex === index ? entry : current)),
		});
	const removeEntry = (index: number) =>
		onChange({ ...lorebook, entries: lorebook.entries.filter((_, itemIndex) => itemIndex !== index) });
	return (
		<div className={`min-w-0 space-y-4 ${className ?? ''}`} {...props}>
			<AiConfigFieldGrid>
				<AiConfigTextField
					label='Lorebook 名称'
					value={lorebook.name}
					disabled={disabled}
					readOnly={readOnly}
					onValueChange={(name) => onChange({ ...lorebook, name: optional(name) })}
				/>
				<AiConfigNumberField
					label='扫描深度'
					value={lorebook.scanDepth}
					integer
					min={1}
					disabled={disabled}
					readOnly={readOnly}
					onValueChange={(scanDepth) => onChange({ ...lorebook, scanDepth })}
				/>
				<AiConfigNumberField
					label='Token 预算'
					value={lorebook.tokenBudget}
					integer
					min={1}
					disabled={disabled}
					readOnly={readOnly}
					onValueChange={(tokenBudget) => onChange({ ...lorebook, tokenBudget })}
				/>
				<AiConfigToggleField
					label='递归扫描'
					checked={lorebook.recursive ?? false}
					disabled={disabled || readOnly}
					onCheckedChange={(recursive) => onChange({ ...lorebook, recursive })}
				/>
			</AiConfigFieldGrid>
			<AiConfigTextareaField
				label='Lorebook 描述'
				value={lorebook.description}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(description) => onChange({ ...lorebook, description: optional(description) })}
			/>
			<div className='flex min-w-0 items-center justify-between gap-2'>
				<div>
					<h4 className='text-sm font-semibold'>Lore 条目</h4>
					<p className='text-base-content/60 text-xs'>
						{lorebook.entries.length} / {boundedMax}
					</p>
				</div>
				{!readOnly ? (
					<button
						type='button'
						className='btn btn-outline btn-sm'
						disabled={disabled || lorebook.entries.length >= boundedMax}
						onClick={() =>
							onChange({ ...lorebook, entries: [...lorebook.entries, createLorebookEntry(lorebook.entries)] })
						}
					>
						<Plus aria-hidden='true' className='size-4' />
						添加条目
					</button>
				) : null}
			</div>
			<div className='divide-base-300 border-base-300 divide-y border-y'>
				{lorebook.entries.length ? (
					loreEntries.map(({ item: entry, key }, index) => (
						<details key={key} className='group py-3' open={index === 0}>
							<summary className='flex cursor-pointer list-none items-center gap-2 text-sm font-medium'>
								<span className='min-w-0 flex-1 truncate'>{entry.name || entry.id}</span>
								<span className='badge badge-outline badge-sm'>{entry.enabled === false ? '停用' : '启用'}</span>
							</summary>
							<div className='mt-3 space-y-4 ps-2'>
								<AiConfigFieldGrid>
									<AiConfigTextField
										required
										label='条目 ID'
										value={entry.id}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(id) => updateEntry(index, { ...entry, id })}
									/>
									<AiConfigTextField
										label='条目名称'
										value={entry.name}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(name) => updateEntry(index, { ...entry, name: optional(name) })}
									/>
									<AiConfigNumberField
										label='优先级'
										value={entry.priority}
										integer
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(priority) => updateEntry(index, { ...entry, priority })}
									/>
									<AiConfigNumberField
										label='插入顺序'
										value={entry.insertionOrder}
										integer
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(insertionOrder) => updateEntry(index, { ...entry, insertionOrder })}
									/>
								</AiConfigFieldGrid>
								<AiConfigStringListField
									label='触发关键词'
									value={entry.keys}
									disabled={disabled}
									readOnly={readOnly}
									onChange={(keys) => updateEntry(index, { ...entry, keys })}
								/>
								<AiConfigStringListField
									label='次级关键词'
									value={entry.secondaryKeys}
									disabled={disabled}
									readOnly={readOnly}
									onChange={(secondaryKeys) => updateEntry(index, { ...entry, secondaryKeys })}
								/>
								<AiConfigTextareaField
									required
									label='内容'
									rows={6}
									value={entry.content}
									disabled={disabled}
									readOnly={readOnly}
									onValueChange={(content) => updateEntry(index, { ...entry, content })}
								/>
								<AiConfigFieldGrid className='lg:grid-cols-3'>
									<AiConfigToggleField
										label='启用'
										checked={entry.enabled ?? true}
										disabled={disabled || readOnly}
										onCheckedChange={(enabled) => updateEntry(index, { ...entry, enabled })}
									/>
									<AiConfigToggleField
										label='常量条目'
										checked={entry.constant ?? false}
										disabled={disabled || readOnly}
										onCheckedChange={(constant) => updateEntry(index, { ...entry, constant })}
									/>
									<AiConfigToggleField
										label='区分大小写'
										checked={entry.caseSensitive ?? false}
										disabled={disabled || readOnly}
										onCheckedChange={(caseSensitive) => updateEntry(index, { ...entry, caseSensitive })}
									/>
									<AiConfigToggleField
										label='正则表达式'
										checked={entry.useRegex ?? false}
										disabled={disabled || readOnly}
										onCheckedChange={(useRegex) => updateEntry(index, { ...entry, useRegex })}
									/>
								</AiConfigFieldGrid>
								{!readOnly ? (
									<div className='flex justify-end'>
										<button
											type='button'
											className='btn btn-ghost btn-sm text-error'
											disabled={disabled}
											onClick={() => removeEntry(index)}
										>
											<Trash2 aria-hidden='true' className='size-4' />
											删除条目
										</button>
									</div>
								) : null}
							</div>
						</details>
					))
				) : (
					<div className='text-base-content/55 py-6 text-center text-sm'>暂无 Lore 条目</div>
				)}
			</div>
			<JsonValueEditor
				label='外部 Lorebook 绑定'
				value={lorebook.bindings}
				disabled={disabled}
				readOnly={readOnly}
				onChange={(bindings) => onChange({ ...lorebook, bindings: bindings as PersonaLorebook['bindings'] })}
			/>
			<JsonValueEditor
				label='Lorebook Extensions'
				value={lorebook.extensions ?? {}}
				disabled={disabled}
				readOnly={readOnly}
				onChange={(extensions) => onChange({ ...lorebook, extensions: extensions as PersonaLorebook['extensions'] })}
			/>
		</div>
	);
}

export function createLorebookEntry(entries: readonly LorebookEntry[]): LorebookEntry {
	let suffix = entries.length + 1;
	while (entries.some((entry) => entry.id === `lore-${suffix}`)) suffix++;
	return { id: `lore-${suffix}`, keys: [], content: '', enabled: true };
}

function optional(value: string): string | undefined {
	return value.trim() ? value : undefined;
}

'use client';

import type { PersonaAsset } from '@wener/ai/agent/persona';
import { Plus, Trash2 } from 'lucide-react';
import type { ComponentPropsWithRef } from 'react';
import {
	AiConfigFieldGrid,
	AiConfigNumberField,
	AiConfigSelectField,
	AiConfigStringListField,
	AiConfigTextareaField,
	AiConfigTextField,
	AiConfigToggleField,
	useStableListEntries,
} from '../../ui/ai-config-editor';

const assetTypes = ['avatar', 'icon', 'background', 'emotion', 'voice', 'model', 'document', 'other'].map((value) => ({
	value,
	label: value,
}));
export type PersonaAssetsEditorProps = Omit<ComponentPropsWithRef<'div'>, 'onChange'> & {
	value: readonly PersonaAsset[];
	onChange: (value: PersonaAsset[]) => void;
	disabled?: boolean;
	readOnly?: boolean;
	maxAssets?: number;
};

export function PersonaAssetsEditor({
	value,
	onChange,
	disabled = false,
	readOnly = false,
	maxAssets = 64,
	className,
	...props
}: PersonaAssetsEditorProps) {
	const boundedMax = Number.isInteger(maxAssets) ? Math.max(1, Math.min(maxAssets, 256)) : 64;
	const assetEntries = useStableListEntries(value, 'persona-asset');
	const update = (index: number, asset: PersonaAsset) =>
		onChange(value.map((current, itemIndex) => (itemIndex === index ? asset : current)));
	return (
		<div className={`min-w-0 space-y-3 ${className ?? ''}`} {...props}>
			<div className='flex items-center justify-between gap-2'>
				<p className='text-base-content/60 text-xs'>
					{value.length} / {boundedMax} 个 manifest；仅保存 URI 和元数据。
				</p>
				{!readOnly ? (
					<button
						type='button'
						className='btn btn-outline btn-sm'
						disabled={disabled || value.length >= boundedMax}
						onClick={() => onChange([...value, createPersonaAsset(value)])}
					>
						<Plus aria-hidden='true' className='size-4' />
						添加资源
					</button>
				) : null}
			</div>
			<div className='divide-base-300 border-base-300 divide-y border-y'>
				{value.length ? (
					assetEntries.map(({ item: asset, key }, index) => (
						<details key={key} className='py-3' open={index === 0}>
							<summary className='flex cursor-pointer list-none items-center gap-2 text-sm font-medium'>
								<span className='min-w-0 flex-1 truncate'>{asset.name || asset.id}</span>
								<span className='badge badge-outline badge-sm'>{asset.type}</span>
							</summary>
							<div className='mt-3 space-y-4 ps-2'>
								<AiConfigFieldGrid>
									<AiConfigTextField
										required
										label='资源 ID'
										value={asset.id}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(id) => update(index, { ...asset, id })}
									/>
									<AiConfigSelectField
										required
										label='资源类型'
										value={asset.type}
										options={assetTypes}
										disabled={disabled || readOnly}
										onValueChange={(type) => update(index, { ...asset, type: type as PersonaAsset['type'] })}
									/>
									<AiConfigTextField
										required
										type='url'
										label='资源 URI'
										value={asset.uri}
										placeholder='https://cdn.example.com/persona/avatar.png'
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(uri) => update(index, { ...asset, uri })}
									/>
									<AiConfigTextField
										label='名称'
										value={asset.name}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(name) => update(index, { ...asset, name: optional(name) })}
									/>
									<AiConfigTextField
										label='Media Type'
										value={asset.mediaType}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(mediaType) => update(index, { ...asset, mediaType: optional(mediaType) })}
									/>
									<AiConfigTextField
										label='Checksum'
										value={asset.checksum}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(checksum) => update(index, { ...asset, checksum: optional(checksum) })}
									/>
									<AiConfigNumberField
										label='大小（bytes）'
										value={asset.size}
										integer
										min={0}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(size) => update(index, { ...asset, size })}
									/>
								</AiConfigFieldGrid>
								<AiConfigTextareaField
									label='描述'
									value={asset.description}
									disabled={disabled}
									readOnly={readOnly}
									onValueChange={(description) => update(index, { ...asset, description: optional(description) })}
								/>
								<AiConfigStringListField
									label='资源标签'
									value={asset.tags}
									disabled={disabled}
									readOnly={readOnly}
									onChange={(tags) => update(index, { ...asset, tags })}
								/>
								<AiConfigFieldGrid>
									<AiConfigTextField
										label='License'
										value={asset.rights?.license}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(license) =>
											update(index, { ...asset, rights: { ...asset.rights, license: optional(license) } })
										}
									/>
									<AiConfigTextField
										label='Rights Holder'
										value={asset.rights?.rightsHolder}
										disabled={disabled}
										readOnly={readOnly}
										onValueChange={(rightsHolder) =>
											update(index, { ...asset, rights: { ...asset.rights, rightsHolder: optional(rightsHolder) } })
										}
									/>
									<AiConfigToggleField
										label='允许再分发'
										checked={asset.rights?.redistributable ?? false}
										disabled={disabled || readOnly}
										onCheckedChange={(redistributable) =>
											update(index, { ...asset, rights: { ...asset.rights, redistributable } })
										}
									/>
								</AiConfigFieldGrid>
								{!readOnly ? (
									<div className='flex justify-end'>
										<button
											type='button'
											className='btn btn-ghost btn-sm text-error'
											disabled={disabled}
											onClick={() => onChange(value.filter((_, itemIndex) => itemIndex !== index))}
										>
											<Trash2 aria-hidden='true' className='size-4' />
											删除资源
										</button>
									</div>
								) : null}
							</div>
						</details>
					))
				) : (
					<div className='text-base-content/55 py-6 text-center text-sm'>暂无资源 manifest</div>
				)}
			</div>
		</div>
	);
}

export function createPersonaAsset(assets: readonly PersonaAsset[]): PersonaAsset {
	let suffix = assets.length + 1;
	while (assets.some((asset) => asset.id === `asset-${suffix}`)) suffix++;
	return { id: `asset-${suffix}`, type: 'other', uri: 'https://cdn.example.com/persona/asset' };
}

function optional(value: string): string | undefined {
	return value.trim() ? value : undefined;
}

import type { Persona } from '@wener/ai/agent/persona';
import { AiConfigFieldGrid, AiConfigStringListField, AiConfigTextareaField } from '../../ui/ai-config-editor';

export type PersonaSectionFieldsProps = {
	value: Persona;
	onChange: (value: Persona) => void;
	disabled?: boolean;
	readOnly?: boolean;
};

export function PersonaAuthoringFields({
	value,
	onChange,
	disabled = false,
	readOnly = false,
}: PersonaSectionFieldsProps) {
	const patch = (next: Partial<NonNullable<Persona['authoring']>>) =>
		onChange({ ...value, authoring: { ...value.authoring, ...next } });
	return (
		<AiConfigFieldGrid>
			<AiConfigTextareaField
				label='背景'
				value={value.authoring?.background}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(background) => patch({ background: optional(background) })}
			/>
			<AiConfigTextareaField
				label='性格'
				value={value.authoring?.personality}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(personality) => patch({ personality: optional(personality) })}
			/>
			<AiConfigTextareaField
				label='行为策略'
				value={value.authoring?.behaviorPolicy}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(behaviorPolicy) => patch({ behaviorPolicy: optional(behaviorPolicy) })}
			/>
			<AiConfigTextareaField
				label='语言风格'
				value={value.authoring?.speechStyle}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(speechStyle) => patch({ speechStyle: optional(speechStyle) })}
			/>
			<AiConfigStringListField
				label='价值观'
				value={value.authoring?.values}
				disabled={disabled}
				readOnly={readOnly}
				onChange={(values) => patch({ values })}
			/>
			<AiConfigStringListField
				label='目标'
				value={value.authoring?.goals}
				disabled={disabled}
				readOnly={readOnly}
				onChange={(goals) => patch({ goals })}
			/>
			<AiConfigStringListField
				label='缺点'
				value={value.authoring?.flaws}
				disabled={disabled}
				readOnly={readOnly}
				onChange={(flaws) => patch({ flaws })}
			/>
			<AiConfigStringListField
				label='示例对话'
				value={value.authoring?.exampleDialogue}
				disabled={disabled}
				readOnly={readOnly}
				onChange={(exampleDialogue) => patch({ exampleDialogue })}
			/>
		</AiConfigFieldGrid>
	);
}

export function PersonaPromptFields({
	value,
	onChange,
	disabled = false,
	readOnly = false,
}: PersonaSectionFieldsProps) {
	const patch = (next: Partial<NonNullable<Persona['prompts']>>) =>
		onChange({ ...value, prompts: { ...value.prompts, ...next } });
	return (
		<div className='grid gap-4 lg:grid-cols-2'>
			<AiConfigTextareaField
				label='System Prompt'
				rows={6}
				value={value.prompts?.system}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(system) => patch({ system: optional(system) })}
			/>
			<AiConfigTextareaField
				label='Persona Prompt'
				rows={6}
				value={value.prompts?.persona}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(persona) => patch({ persona: optional(persona) })}
			/>
			<AiConfigTextareaField
				label='场景'
				rows={5}
				value={value.prompts?.scenario}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(scenario) => patch({ scenario: optional(scenario) })}
			/>
			<AiConfigTextareaField
				label='历史后指令'
				rows={5}
				value={value.prompts?.postHistoryInstructions}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(postHistoryInstructions) =>
					patch({ postHistoryInstructions: optional(postHistoryInstructions) })
				}
			/>
		</div>
	);
}

function optional(value: string): string | undefined {
	return value.trim() ? value : undefined;
}

import type { Persona } from '@wener/ai/agent/persona';
import {
	AiConfigFieldGrid,
	AiConfigSelectField,
	AiConfigTextField,
	AiConfigToggleField,
} from '../../ui/ai-config-editor';

const visibility = ['private', 'unlisted', 'public'].map((value) => ({ value, label: value }));
const ratings = ['unknown', 'general', 'teen', 'mature', 'restricted'].map((value) => ({ value, label: value }));
const reviewStatuses = ['draft', 'pending', 'approved', 'rejected', 'withdrawn'].map((value) => ({
	value,
	label: value,
}));

export type PersonaGovernanceFieldsProps = {
	value: Persona;
	onChange: (value: Persona) => void;
	disabled?: boolean;
	readOnly?: boolean;
};

export function PersonaGovernanceFields({
	value,
	onChange,
	disabled = false,
	readOnly = false,
}: PersonaGovernanceFieldsProps) {
	const locked = disabled || readOnly;
	const patchGovernance = (next: Partial<NonNullable<Persona['governance']>>) =>
		onChange({ ...value, governance: { ...value.governance, ...next } });
	const patchRights = (next: Partial<NonNullable<Persona['rights']>>) =>
		onChange({ ...value, rights: { ...value.rights, ...next } });
	return (
		<AiConfigFieldGrid>
			<AiConfigSelectField
				label='可见性'
				value={value.governance?.visibility}
				options={visibility}
				disabled={locked}
				onValueChange={(next) =>
					patchGovernance({ visibility: next ? (next as NonNullable<Persona['governance']>['visibility']) : undefined })
				}
			/>
			<AiConfigSelectField
				label='内容分级'
				value={value.governance?.contentRating}
				options={ratings}
				disabled={locked}
				onValueChange={(next) =>
					patchGovernance({
						contentRating: next ? (next as NonNullable<Persona['governance']>['contentRating']) : undefined,
					})
				}
			/>
			<AiConfigSelectField
				label='审核状态'
				value={value.governance?.reviewStatus}
				options={reviewStatuses}
				disabled={locked}
				onValueChange={(next) =>
					patchGovernance({
						reviewStatus: next ? (next as NonNullable<Persona['governance']>['reviewStatus']) : undefined,
					})
				}
			/>
			<AiConfigTextField
				label='来源说明'
				value={value.governance?.provenance}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(provenance) => patchGovernance({ provenance: optional(provenance) })}
			/>
			<AiConfigTextField
				type='url'
				label='来源 URL'
				value={value.governance?.sourceUrl}
				placeholder='https://example.com/source'
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(sourceUrl) => patchGovernance({ sourceUrl: optional(sourceUrl) })}
			/>
			<AiConfigTextField
				label='License'
				value={value.rights?.license}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(license) => patchRights({ license: optional(license) })}
			/>
			<AiConfigTextField
				label='Rights Holder'
				value={value.rights?.rightsHolder}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(rightsHolder) => patchRights({ rightsHolder: optional(rightsHolder) })}
			/>
			<AiConfigTextField
				label='Source'
				value={value.rights?.source}
				disabled={disabled}
				readOnly={readOnly}
				onValueChange={(source) => patchRights({ source: optional(source) })}
			/>
			<AiConfigToggleField
				label='允许再分发'
				checked={value.rights?.redistributable ?? false}
				disabled={locked}
				onCheckedChange={(redistributable) => patchRights({ redistributable })}
			/>
			<AiConfigToggleField
				label='允许商业使用'
				checked={value.rights?.commercialUse ?? false}
				disabled={locked}
				onCheckedChange={(commercialUse) => patchRights({ commercialUse })}
			/>
		</AiConfigFieldGrid>
	);
}

function optional(value: string): string | undefined {
	return value.trim() ? value : undefined;
}

'use client';

import { type Persona, PersonaSchema } from '@wener/ai/agent/persona';
import type { ReactNode } from 'react';
import {
	AiConfigEditor,
	AiConfigFieldGrid,
	AiConfigFieldSlot,
	AiConfigFormSection,
	AiConfigStringListField,
	AiConfigTextareaField,
	AiConfigTextField,
	aiConfigFieldError,
	JsonValueEditor,
	mergeResourceEditorMessages,
	useAiConfigDraft,
} from '../../ui/ai-config-editor';
import type {
	AgentPersonaEditorField,
	AgentPersonaEditorMessages,
	AgentPersonaEditorProps,
} from './agent-persona-editor-types';
import { PersonaAssetsEditor } from './persona-assets-editor';
import { PersonaAuthoringFields, PersonaPromptFields } from './persona-authoring-fields';
import { PersonaGovernanceFields } from './persona-governance-fields';
import { PersonaLorebookEditor } from './persona-lorebook-editor';

export const defaultAgentPersona: Persona = PersonaSchema.parse({
	id: 'persona-new',
	name: '新角色',
	version: '1.0.0',
});
const defaultMessages: AgentPersonaEditorMessages = {
	title: 'Agent Persona 配置',
	description: '编辑角色 authoring、prompts、Lorebook、资源 manifest 与治理信息。',
	sections: {
		identity: '身份',
		authoring: '性格与行为',
		prompts: 'Prompts 与问候语',
		author: '作者',
		lorebook: 'Lorebook',
		assets: '资源 Manifest',
		governance: '来源、治理与权利',
		extensions: 'Metadata 与 Extensions',
	},
	fields: {
		id: 'ID',
		name: '名称',
		version: '版本',
		title: '显示名称',
		nickname: '昵称',
		description: '描述',
		author: '作者',
		creatorNotes: '创作者备注',
		tags: '标签',
		language: '语言',
		authoring: 'Authoring',
		prompts: 'Prompts',
		greetings: '问候语',
		groupGreetings: '群组问候语',
		lorebook: 'Lorebook',
		assets: '资源',
		governance: '治理',
		rights: 'Rights',
		metadata: 'Metadata',
		extensions: 'Extensions',
	},
};

export function AgentPersonaEditor({
	value,
	onChange,
	onSubmit,
	schema = PersonaSchema,
	validationMode,
	disabled = false,
	readOnly = false,
	messages: overrides,
	slots,
	maxLoreEntries = 64,
	maxAssets = 64,
	...props
}: AgentPersonaEditorProps) {
	const messages = mergeResourceEditorMessages(defaultMessages, overrides);
	const controller = useAiConfigDraft({
		value,
		fallbackValue: defaultAgentPersona,
		schema,
		onChange,
		onSubmit,
		validationMode,
	});
	const draft = controller.draft;
	const patch = (next: Partial<Persona>) => controller.setDraft({ ...draft, ...next });
	const field = (name: AgentPersonaEditorField, defaultField: ReactNode) => (
		<AiConfigFieldSlot
			name={name}
			draft={draft}
			disabled={disabled}
			readOnly={readOnly}
			error={aiConfigFieldError(controller.visibleIssues, name)}
			defaultField={defaultField}
			onDraftChange={controller.setDraft}
			slots={slots}
		/>
	);
	return (
		<AiConfigEditor
			{...props}
			title={messages.title}
			description={messages.description}
			controller={controller}
			messages={messages.editor}
			slots={slots}
			disabled={disabled}
			readOnly={readOnly}
			showSubmit={Boolean(onSubmit)}
		>
			<AiConfigFormSection title={messages.sections.identity}>
				<AiConfigFieldGrid>
					{field(
						'id',
						<AiConfigTextField
							required
							label={messages.fields.id}
							value={draft.id}
							error={aiConfigFieldError(controller.visibleIssues, 'id')}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(id) => patch({ id })}
						/>,
					)}
					{field(
						'name',
						<AiConfigTextField
							required
							label={messages.fields.name}
							value={draft.name}
							error={aiConfigFieldError(controller.visibleIssues, 'name')}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(name) => patch({ name })}
						/>,
					)}
					{field(
						'version',
						<AiConfigTextField
							required
							label={messages.fields.version}
							value={draft.version}
							error={aiConfigFieldError(controller.visibleIssues, 'version')}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(version) => patch({ version })}
						/>,
					)}
					{field(
						'title',
						<AiConfigTextField
							label={messages.fields.title}
							value={draft.title}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(title) => patch({ title: optional(title) })}
						/>,
					)}
					{field(
						'nickname',
						<AiConfigTextField
							label={messages.fields.nickname}
							value={draft.nickname}
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(nickname) => patch({ nickname: optional(nickname) })}
						/>,
					)}
					{field(
						'language',
						<AiConfigTextField
							label={messages.fields.language}
							value={draft.language}
							placeholder='zh-CN'
							disabled={disabled}
							readOnly={readOnly}
							onValueChange={(language) => patch({ language: optional(language) })}
						/>,
					)}
				</AiConfigFieldGrid>
				{field(
					'description',
					<AiConfigTextareaField
						wrapperClassName='mt-4'
						label={messages.fields.description}
						value={draft.description}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(description) => patch({ description: optional(description) })}
					/>,
				)}
				{field(
					'tags',
					<AiConfigStringListField
						className='mt-4'
						label={messages.fields.tags}
						value={draft.tags}
						disabled={disabled}
						readOnly={readOnly}
						onChange={(tags) => patch({ tags })}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.authoring}>
				{field(
					'authoring',
					<PersonaAuthoringFields
						value={draft}
						onChange={controller.setDraft}
						disabled={disabled}
						readOnly={readOnly}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.prompts}>
				{field(
					'prompts',
					<PersonaPromptFields value={draft} onChange={controller.setDraft} disabled={disabled} readOnly={readOnly} />,
				)}
				<div className='mt-4 grid gap-4 lg:grid-cols-2'>
					{field(
						'greetings',
						<AiConfigStringListField
							label={messages.fields.greetings}
							value={draft.greetings}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(greetings) => patch({ greetings })}
						/>,
					)}
					{field(
						'groupGreetings',
						<AiConfigStringListField
							label={messages.fields.groupGreetings}
							value={draft.groupGreetings}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(groupGreetings) => patch({ groupGreetings })}
						/>,
					)}
				</div>
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.author}>
				<AiConfigFieldGrid>
					<AiConfigTextField
						label='作者名称'
						value={draft.author?.name}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(name) => patch({ author: name.trim() ? { ...draft.author, name } : undefined })}
					/>
					<AiConfigTextField
						label='作者 ID'
						value={draft.author?.id}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(id) => draft.author && patch({ author: { ...draft.author, id: optional(id) } })}
					/>
					<AiConfigTextField
						type='url'
						label='作者 URL'
						value={draft.author?.url}
						placeholder='https://example.com/author'
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(url) => draft.author && patch({ author: { ...draft.author, url: optional(url) } })}
					/>
					<AiConfigTextField
						label='联系方式'
						value={draft.author?.contact}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(contact) =>
							draft.author && patch({ author: { ...draft.author, contact: optional(contact) } })
						}
					/>
				</AiConfigFieldGrid>
				{field(
					'creatorNotes',
					<AiConfigTextareaField
						wrapperClassName='mt-4'
						label={messages.fields.creatorNotes}
						value={draft.creatorNotes}
						disabled={disabled}
						readOnly={readOnly}
						onValueChange={(creatorNotes) => patch({ creatorNotes: optional(creatorNotes) })}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.lorebook}>
				{field(
					'lorebook',
					<PersonaLorebookEditor
						value={draft.lorebook}
						maxEntries={maxLoreEntries}
						disabled={disabled}
						readOnly={readOnly}
						onChange={(lorebook) => patch({ lorebook })}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.assets}>
				{field(
					'assets',
					<PersonaAssetsEditor
						value={draft.assets}
						maxAssets={maxAssets}
						disabled={disabled}
						readOnly={readOnly}
						onChange={(assets) => patch({ assets })}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.governance}>
				{field(
					'governance',
					<PersonaGovernanceFields
						value={draft}
						onChange={controller.setDraft}
						disabled={disabled}
						readOnly={readOnly}
					/>,
				)}
			</AiConfigFormSection>
			<AiConfigFormSection title={messages.sections.extensions}>
				<div className='grid gap-4 lg:grid-cols-2'>
					{field(
						'metadata',
						<JsonValueEditor
							label={messages.fields.metadata}
							value={draft.metadata ?? {}}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(metadata) => patch({ metadata: metadata as Persona['metadata'] })}
						/>,
					)}
					{field(
						'extensions',
						<JsonValueEditor
							label={messages.fields.extensions}
							value={draft.extensions ?? {}}
							disabled={disabled}
							readOnly={readOnly}
							onChange={(extensions) => patch({ extensions: extensions as Persona['extensions'] })}
						/>,
					)}
				</div>
			</AiConfigFormSection>
		</AiConfigEditor>
	);
}

function optional(value: string): string | undefined {
	return value.trim() ? value : undefined;
}

